$page_title='Tambah Kelas';$active='kelas';$prefix='../';include '../includes/header.php';?>
<div class="page-heading"><div><h1>Tambah Kelas</h1><p>Tambahkan rombongan belajar untuk tingkat SMP.</p></div><a href="index.php" class="btn btn-light border">Kembali</a></div><div class="panel"><div class="panel-body"><?php if($error):?><div class="alert alert-danger"><?= e($error) ?></div><?php endif;?><form method="post"><div class="row g-3"><div class="col-md-6"><label class="form-label">Nama Kelas *</label><input name="nama_kelas" class="form-control" required placeholder="Contoh: VII-A" value="<?= e($row['nama_kelas']) ?>"><div class="form-text">Gunakan nama yang konsisten, misalnya VII-A, VIII-B, atau IX-A.</div></div><div class="col-md-6"><label class="form-label">Tingkat *</label><select name="tingkat" class="form-select" required><?php foreach(['VII','VIII','IX'] as $t):?><option value="<?= $t ?>" <?= $row['tingkat']===$t?'selected':'' ?>><?= $t ?> — Kelas <?= $t ?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Wali Kelas</label><input name="wali_kelas" class="form-control" value="<?= e($row['wali_kelas']) ?>"></div><div class="col-md-6"><label class="form-label">Status</label><select name="status" class="form-select"><option value="aktif">Aktif</option><option value="nonaktif">Nonaktif</option></select></div></div><div class="d-flex gap-2 mt-4"><button class="btn btn-primary">Simpan Kelas</button><a href="index.php" class="btn btn-light border">Batal</a></div></form></div></div><?php include '../includes/footer.php';?>